        /// <summary>
        /// Gets the number of codes ND's table covers.
        /// </summary>
        public const int Count = 256;

        /// <summary>
        /// Returns ND's text for a SINTRAN error code.
        /// </summary>
        /// <param name="code">
        /// The error number as it travels on the wire.
        /// </param>
        /// <returns>
        /// ND's own wording, or a plain marker when the code is outside the table.
        /// </returns>
        public static string Describe(int code)
        {
            if (code < 0 || code >= Texts.Length)
            {
                return "(outside SINTRAN's error table)";
            }

            return Texts[code];
        }

        /// <summary>
        /// Returns ND's recovery disposition for a SINTRAN error code.
        /// </summary>
        /// <param name="code">
        /// The error number as it travels on the wire.
        /// </param>
        /// <returns>
        /// The disposition, or <see cref="XmsgErrorDisposition.Unknown"/> outside the table.
        /// </returns>
        public static XmsgErrorDisposition DispositionOf(int code)
        {
            if (code < 0 || code >= Dispositions.Length)
            {
                return XmsgErrorDisposition.Unknown;
            }

            return Dispositions[code];
        }

        /// <summary>
        /// Reports whether ND's table gives this code a real meaning.
        /// </summary>
        /// <param name="code">
        /// The error number as it travels on the wire.
        /// </param>
        /// <returns>
        /// False for a code outside the table, and for one ND fills with a placeholder.
        /// </returns>
        /// <remarks>
        /// Worth checking before choosing a code to SEND: a placeholder number makes a real
        /// machine print "ERROR CODE OUTSIDE RANGE", which tells the user nothing.
        /// </remarks>
        public static bool IsMeaningful(int code)
        {
            if (code < 0 || code >= Meaningful.Length)
            {
                return false;
            }

            return Meaningful[code];
        }
    }
